<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
use App\Core\Database;
$pdo=Database::connection();$id=(int)($_GET['id']??0);$requestedGroup=(int)($_GET['career_group_id']??0);$dance=(string)($_GET['dance']??'bachata');if(!in_array($dance,['bachata','salsa','dance_cup'],true))$dance='bachata';
if($requestedGroup>0){$s=$pdo->prepare("SELECT c.*,g.display_name career_display_name FROM bdc_competitors c JOIN bdc_competitor_career_groups g ON g.id=c.career_group_id WHERE c.career_group_id=:g AND c.status='active' ORDER BY FIELD(c.dance_role,'follower','leader'),c.id");$s->execute(['g'=>$requestedGroup]);$profiles=$s->fetchAll();}else{$s=$pdo->prepare("SELECT c.*,g.display_name career_display_name FROM bdc_competitors c LEFT JOIN bdc_competitor_career_groups g ON g.id=c.career_group_id WHERE c.id=:id AND c.status='active'");$s->execute(['id'=>$id]);$first=$s->fetch();if(!$first){http_response_code(404);exit('Competitor not found');}if(!empty($first['career_group_id'])){$s=$pdo->prepare("SELECT c.*,g.display_name career_display_name FROM bdc_competitors c JOIN bdc_competitor_career_groups g ON g.id=c.career_group_id WHERE c.career_group_id=:g AND c.status='active' ORDER BY FIELD(c.dance_role,'follower','leader'),c.id");$s->execute(['g'=>(int)$first['career_group_id']]);$profiles=$s->fetchAll();}else{$profiles=[$first];}}
if(!$profiles){http_response_code(404);exit('Career profile not found');}$primary=$profiles[0];$displayName=trim((string)($primary['career_display_name']??''))?:$primary['exact_name'];$ids=array_map(fn($p)=>(int)$p['id'],$profiles);$photo='';$country='';foreach($profiles as $p){if($photo===''&&!empty($p['photo_url']))$photo=$p['photo_url'];if($country===''&&!empty($p['country']))$country=$p['country'];}$photo=$photo?:url('public/assets/img/default-competitor.svg');
$rows=[];$roleStats=[];$totalPoints=0.0;$events=0;$wins=0;$podiums=0;$finals=0;$divisionPoints=['novice'=>0.0,'intermediate'=>0.0,'advanced'=>0.0];$cupRows=[];
if($dance==='dance_cup'){$ph=implode(',',array_fill(0,count($ids),'?'));$q=$pdo->prepare("SELECT d.*,e.name event_name,e.event_date,c.bdc_id FROM bdc_dance_cup_results d JOIN bdc_events e ON e.id=d.event_id LEFT JOIN bdc_competitors c ON c.id=d.competitor_id WHERE d.competitor_id IN ($ph) ORDER BY e.event_date DESC,d.id DESC");$q->execute($ids);$cupRows=$q->fetchAll();$events=count($cupRows);foreach($cupRows as $r){$pl=(int)($r['placement']??0);if($pl===1)$wins++;if($pl>=1&&$pl<=3)$podiums++;}}
else{foreach($profiles as $p){$pid=(int)$p['id'];$role=(string)$p['dance_role'];$h=$pdo->prepare("SELECT e.name event_name,e.event_date,r.division,r.dance_role,r.placement,r.finalist_status,r.partner_name,r.points_awarded FROM bdc_participant_results r LEFT JOIN bdc_events e ON e.id=r.event_id WHERE r.competitor_id=:id AND r.dance_style=:dance AND r.points_awarded>0 ORDER BY e.event_date DESC,r.id DESC");$h->execute(['id'=>$pid,'dance'=>$dance]);$personRows=$h->fetchAll();if(!$personRows){$h=$pdo->prepare("SELECT e.name event_name,e.event_date,r.division,r.dance_role,r.placement,'participant' finalist_status,NULL partner_name,r.points points_awarded FROM bdc_point_transactions r LEFT JOIN bdc_events e ON e.id=r.event_id WHERE r.competitor_id=:id AND r.dance_style=:dance AND r.points>0 ORDER BY e.event_date DESC,r.id DESC");$h->execute(['id'=>$pid,'dance'=>$dance]);$personRows=$h->fetchAll();}$rs=['points'=>0.0,'events'=>0,'wins'=>0,'podiums'=>0,'finals'=>0,'bdc_id'=>$p['bdc_id'],'name'=>$p['exact_name']];foreach($personRows as $r){$r['_competitor_id']=$pid;$r['_bdc_id']=$p['bdc_id'];$rows[]=$r;$pts=(float)$r['points_awarded'];$rs['points']+=$pts;$totalPoints+=$pts;if(isset($divisionPoints[$r['division']]))$divisionPoints[$r['division']]+=$pts;$rs['events']++;$events++;$pl=(int)$r['placement'];if($pl===1){$rs['wins']++;$wins++;}if($pl>=1&&$pl<=3){$rs['podiums']++;$podiums++;}if(in_array($r['finalist_status'],['finalist','placed','winner'],true)||$pl>0){$rs['finals']++;$finals++;}}$roleStats[$role]=$rs;}usort($rows,fn($a,$b)=>strcmp((string)$b['event_date'],(string)$a['event_date']));}
function disciplineLabel(string $dance):string{return match($dance){'salsa'=>'Salsa','dance_cup'=>'BDC Dance Cup',default=>'Bachata'};}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($displayName)?> | BDC Career Profile</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="<?=e(url('public/assets/css/app.css'))?>" rel="stylesheet"><style>.profile-photo{width:120px;height:150px;object-fit:cover;border-radius:12px}.stat{background:#fff;border-radius:12px;padding:1rem;box-shadow:0 .25rem .8rem rgba(0,0,0,.06)}.role-card{border-left:5px solid #212529}.role-id{font-family:monospace}.discipline-tabs .btn{min-width:150px}@media(max-width:575px){.discipline-tabs .btn{flex:1 1 100%}}</style></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container"><a class="navbar-brand" href="<?=e(url())?>">Bachata Dance Council</a><div class="d-flex gap-2"><a class="btn btn-warning btn-sm" href="https://bachatadancecouncil.com/">🏠 BDC Home</a><a class="btn btn-outline-light btn-sm" href="<?=e(url('leaderboard/?dance='.$dance))?>">Leaderboard</a></div></div></nav><main class="container py-5"><div class="card border-0 shadow-sm mb-4"><div class="card-body d-flex flex-column flex-md-row gap-4 align-items-md-center"><div class="text-center"><img class="profile-photo d-block" src="<?=e($photo)?>" alt="<?=e($displayName)?>"><?php if($flag=country_flag_url($country)):?><img style="width:42px;height:28px;object-fit:cover;border:1px solid #d1d5db;border-radius:4px;margin-top:7px" src="<?=e($flag)?>" alt="<?=e($country)?> flag"><?php endif;?></div><div class="flex-grow-1"><div class="text-uppercase small text-muted fw-semibold">BDC Competitor Profile</div><h1 class="mb-1"><?=e($displayName)?></h1><div class="text-muted mb-2"><?php foreach($profiles as $i=>$p):?><?=$i?' · ':''?><?=e($p['bdc_id'])?> (<?=e(ucfirst($p['dance_role']))?>)<?php endforeach;?></div><div><strong>Country:</strong> <?=e($country?:'—')?></div></div></div></div><div class="d-flex gap-2 flex-wrap discipline-tabs mb-4"><?php foreach(['bachata'=>'Bachata','salsa'=>'Salsa','dance_cup'=>'BDC Dance Cup'] as $value=>$label):?><a class="btn <?=$dance===$value?'btn-dark':'btn-outline-dark'?>" href="?<?=!empty($primary['career_group_id'])?'career_group_id='.(int)$primary['career_group_id']:'id='.(int)$primary['id']?>&amp;dance=<?=$value?>"><?=$label?></a><?php endforeach;?></div>
<?php if($dance==='dance_cup'):?><div class="row g-3 mb-4"><div class="col-4"><div class="stat"><div class="text-muted small">Dance Cup Events</div><div class="h3 mb-0"><?=$events?></div></div></div><div class="col-4"><div class="stat"><div class="text-muted small">Wins</div><div class="h3 mb-0"><?=$wins?></div></div></div><div class="col-4"><div class="stat"><div class="text-muted small">Podiums</div><div class="h3 mb-0"><?=$podiums?></div></div></div></div><div class="card border-0 shadow-sm"><div class="card-header bg-white"><strong>BDC Dance Cup History</strong><div class="small text-muted">Placement history only. No BDC points.</div></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Date</th><th>Event</th><th>BDC ID</th><th>Category</th><th>Placement</th></tr></thead><tbody><?php foreach($cupRows as $r):?><tr><td><?=e($r['event_date']?:'—')?></td><td><?=e($r['event_name'])?></td><td><code><?=e($r['bdc_id']?:'—')?></code></td><td><?=e($r['category_name']?:'—')?></td><td><?=e($r['placement']?:'—')?></td></tr><?php endforeach;?><?php if(!$cupRows):?><tr><td colspan="5" class="text-center text-muted py-5">No BDC Dance Cup results yet.</td></tr><?php endif;?></tbody></table></div></div><?php else:?><div class="mb-3"><h2 class="h4 mb-1"><?=e(disciplineLabel($dance))?> Jack & Jill</h2><div class="text-muted">Points and competition history shown only for <?=e(disciplineLabel($dance))?>.</div></div><div class="row g-3 mb-4"><div class="col-6 col-lg-3"><div class="stat"><div class="text-muted small">Novice Points</div><div class="h3 mb-0"><?=number_format($divisionPoints['novice'],1)?></div></div></div><div class="col-6 col-lg-3"><div class="stat"><div class="text-muted small">Intermediate Points</div><div class="h3 mb-0"><?=number_format($divisionPoints['intermediate'],1)?></div></div></div><div class="col-6 col-lg-3"><div class="stat"><div class="text-muted small">Advanced Points</div><div class="h3 mb-0"><?=number_format($divisionPoints['advanced'],1)?></div></div></div><div class="col-6 col-lg-3"><div class="stat"><div class="text-muted small">Events</div><div class="h3 mb-0"><?=$events?></div></div></div></div><div class="row g-3 mb-4"><?php foreach($roleStats as $role=>$s):?><div class="col-md-6"><div class="card role-card h-100 shadow-sm border-0"><div class="card-body"><div class="d-flex justify-content-between"><h2 class="h5"><?=e(ucfirst($role))?> Stats</h2><span class="badge text-bg-dark"><?=number_format((float)$s['points'],1)?> points</span></div><div class="role-id text-muted mb-3"><?=e($s['bdc_id'])?></div><div class="row text-center"><div class="col"><strong><?=$s['events']?></strong><div class="small text-muted">Events</div></div><div class="col"><strong><?=$s['wins']?></strong><div class="small text-muted">Wins</div></div><div class="col"><strong><?=$s['podiums']?></strong><div class="small text-muted">Podiums</div></div><div class="col"><strong><?=$s['finals']?></strong><div class="small text-muted">Finals</div></div></div></div></div></div><?php endforeach;?></div><div class="card border-0 shadow-sm"><div class="card-header bg-white"><strong><?=e(disciplineLabel($dance))?> Competition History</strong></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Date</th><th>Event</th><th>BDC ID</th><th>Division</th><th>Role</th><th>Placement</th><th>Partner</th><th>Points</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['event_date']?:'—')?></td><td><?=e($r['event_name']?:'—')?></td><td><code><?=e($r['_bdc_id'])?></code></td><td><?=e(ucwords(str_replace('_',' ',$r['division'])))?></td><td><?=e(ucfirst($r['dance_role']))?></td><td><?=e($r['placement']?:'—')?></td><td><?=e($r['partner_name']?:'—')?></td><td class="fw-bold"><?=number_format((float)$r['points_awarded'],1)?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="text-center text-muted py-5">No <?=e(disciplineLabel($dance))?> results found.</td></tr><?php endif;?></tbody></table></div></div><?php endif;?></main></body></html>
